relationships.targetSignature:
func(name string, count int) {
		normalize := func(value int) int { return adjust(name, value) }
		i.beans[name] += normalize(count)
	}

relationships.evidence:
deliveries.iter().for_each(|(name, count)| {
            fn adjusted_units(value: i32, adjust: Adjustment) -> i32 {
                KEEP_NONNEGATIVE(adjust(value))
            }
            let normalize = |value: i32| adjusted_units(value, adjust);
            *self.beans.entry(name.to_string()).or

Enum.reduce(deliveries, stock, fn {name, count}, current ->
      normalize = fn value -> max(adjust.(value), 0) end
      beans = Map.update(current.beans, name, normalize.(count), fn previous ->
        previous + normalize.(count)
      end)
      %{current | beans: beans}
    end)
